import * as THREE from 'three';
import {GLTFLoader} from './vendor/examples/jsm/loaders/GLTFLoader.js';
export function assetParts(scene){scene.updateMatrixWorld(true);const parts=[];scene.traverse(o=>{if(!o.isMesh)return;const geometry=o.geometry.clone().applyMatrix4(o.matrixWorld);geometry.computeBoundingBox();geometry.computeBoundingSphere();const material=o.material;if(Array.isArray(material))throw new Error('Unexpected multi material city primitive');if(material.name.includes('Leaf')){material.alphaTest=.5;material.transparent=false;material.side=THREE.DoubleSide;material.depthWrite=true;material.roughness=.9;}parts.push({geometry,material});});return parts;}
export async function loadCityKit(onProgress=()=>{}){const response=await fetch('./assets/city/manifest.json');if(!response.ok)throw new Error('City manifest failed to load');const manifest=await response.json(),kit=new Map(),loader=new GLTFLoader();let count=0;await Promise.all(manifest.assets.map(async asset=>{const gltf=await loader.loadAsync('./assets/city/'+asset.file);kit.set(asset.name,{...asset,parts:assetParts(gltf.scene)});onProgress(++count/manifest.assets.length);}));return {manifest,kit};}
export function cityPlacements(track,manifest){const assets=new Map(manifest.assets.map(a=>[a.name,a])),placements=[],occupied=[];let seed=7621;const random=()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296;};const pose=(s,offset,heading)=>{const p=track.at(s);return {x:p.x+p.tz*offset,y:p.y+.14,z:p.z-p.tx*offset,heading:heading??p.heading};};
 for(let s=20;s<track.length;s+=36){for(const side of [-1,1]){const fraction=s/track.length;let options=fraction>.3&&fraction<.56?['warehouse','warehouse','masonry']:fraction>.56&&fraction<.78?['masonry','limestone','masonry']:['office','limestone','masonry','tower'];const name=options[Math.floor(random()*options.length)],a=assets.get(name),p=track.at(s);let offset=14.7+a.depth/2,position,clear=false;
 for(let attempt=0;attempt<7;attempt++){position=pose(s,side*offset,p.heading-side*Math.PI/2);clear=true;const bounds=a.bounds;for(const u of [bounds.min[0],0,bounds.max[0]])for(const v of [bounds.min[2],bounds.max[2]]){const h=position.heading,x=position.x+Math.cos(h)*u+Math.sin(h)*v,z=position.z-Math.sin(h)*u+Math.cos(h)*v;if(track.project(x,z).dist<13.6**2)clear=false;}if(clear)break;offset+=3;}
 if(!clear||occupied.some(o=>Math.hypot(o.x-position.x,o.z-position.z)<(o.width+a.width)*.4))continue;occupied.push({...position,width:a.width});placements.push({name,...position,scale:1});
 }}
 for(let s=18;s<track.length;s+=22){const district=s/track.length,spacing=district>.3&&district<.56?3:1;if(Math.floor(s/22)%spacing)continue;for(const side of [-1,1]){const p=pose(s,side*12.25);if(track.project(p.x,p.z).dist<11.5**2)continue;placements.push({name:random()>.68?'tree-tall':'tree-broad',...p,heading:random()*Math.PI*2,scale:.85+random()*.25});}}
 for(const s of [track.length*.32,track.length*.49])placements.push({name:'pipe-bridge',...pose(s,0),scale:1});
 for(let s=85;s<track.length;s+=230){const side=Math.floor(s/230)%2?1:-1;placements.push({name:'street-props',...pose(s,side*12,pTrackHeading(s,side)),scale:1});}
 function pTrackHeading(s,side){return track.at(s).heading-side*Math.PI/2;}
 for(let s=44;s<track.length;s+=96)placements.push({name:'hydrant',...pose(s,(Math.floor(s/96)%2?1:-1)*11),scale:1});
 // A second skyline layer has real architecture and is close enough to establish depth.
 for(let i=0;i<28;i++){const angle=i/28*Math.PI*2,x=170+Math.sin(angle)*520,z=50+Math.cos(angle)*490;if(track.project(x,z).dist<90**2)continue;placements.push({name:i%3?'office':'tower',x,y:0,z,heading:angle+.25,scale:1.1+random()*.5,distant:true});}
 return placements;
}
export function installCity(scene,track,manifest,kit){const placements=cityPlacements(track,manifest),groups=new Map();for(const p of placements){if(!groups.has(p.name))groups.set(p.name,[]);groups.get(p.name).push(p);}let draws=0,triangles=0;for(const [name,list] of groups){const asset=kit.get(name);for(const part of asset.parts){const mesh=new THREE.InstancedMesh(part.geometry,part.material,list.length),q=new THREE.Quaternion(),matrix=new THREE.Matrix4();list.forEach((p,i)=>{q.setFromAxisAngle(new THREE.Vector3(0,1,0),p.heading);matrix.compose(new THREE.Vector3(p.x,p.y,p.z),q,new THREE.Vector3(p.scale,p.scale,p.scale));mesh.setMatrixAt(i,matrix);});mesh.name='Blender '+name+' / '+part.material.name;mesh.castShadow=true;mesh.receiveShadow=true;if(part.material.alphaTest){mesh.customDepthMaterial=new THREE.MeshDepthMaterial({depthPacking:THREE.RGBADepthPacking,map:part.material.map,alphaTest:.5,side:THREE.DoubleSide});}mesh.computeBoundingSphere();scene.add(mesh);draws++;triangles+=(part.geometry.index?.count??part.geometry.attributes.position.count)/3*list.length;}}
 return {placements,draws,triangles};}
